def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries (not strictly necessary but keeps cache clean)
            # Actually, we only need to check expiry when accessing

            # If key already exists, remove it from order
            if key in cache:
                del cache[key]
            else:
                # Key is new, check if we need to evict
                # Only count non-expired entries toward capacity
                non_expired = {k: v for k, v in cache.items() if v[1] + ttl > t}
                if len(non_expired) >= capacity:
                    # Evict the least recently used (first item in OrderedDict)
                    lru_key = next(iter(cache))
                    del cache[lru_key]

            # Add/update the entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            if key in cache:
                value, write_time = cache[key]
                # Check if expired
                if write_time + ttl > t:
                    # Not expired, make it most recently used
                    del cache[key]
                    cache[key] = (value, write_time)
                    results.append(value)
                else:
                    # Expired
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)

    return results

